-- GENERATED by scripts/gen-suites.mjs from registry/db-schema.json — PL Procurement plan. READ-ONLY queries for DBeaver, SIT connection only.
-- Replace {NO} with the document number (e.g. PL26…). Mapping verified: yes — SIT 2026-11-24: PP 385/395, PE 243/250 doc ids are PP_PLAN.PLAN_ID; plan numbers PP260000000000245 / PE260000000000009

-- Status history (PP); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pp_workflow_status w
 where w.doc_type = 'PP'
   and w.doc_id in (select plan_id from ngep_sit.pp_plan where plan_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Status history (PE); the row with is_current = 1 is the current status
select w.doc_type, w.status_id, w.is_current, to_char(w.created_date, 'YYYY-MM-DD HH24:MI:SS') as changed_at,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pp_workflow_status w
 where w.doc_type = 'PE'
   and w.doc_id in (select plan_id from ngep_sit.pp_plan where plan_no = '{NO}')
 order by w.created_date, w.workflow_status_id;

-- Open BPM tasks: who the task is assigned to (task name = activityname)
select activityname, state, assignees, acquiredby, to_char(createddate, 'YYYY-MM-DD HH24:MI:SS') as created
  from SIT01_SOAINFRA.wftask@SITSOA
 where customattributestring1 = '{NO}'
 order by createddate;

-- Every status a PP has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pp_workflow_status w
 where w.doc_type = 'PP' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;

-- Every status a PE has used on SIT in the last year (EN/BM), to see where a document can stop
select w.status_id, count(*) as rows_,
       (select e.status_name from ngep_sit.pm_status_desc e where e.status_id = w.status_id and e.language_code = 'en' and rownum = 1) as status_en,
       (select m.status_name from ngep_sit.pm_status_desc m where m.status_id = w.status_id and m.language_code = 'ms' and rownum = 1) as status_bm
  from ngep_sit.pp_workflow_status w
 where w.doc_type = 'PE' and w.created_date > sysdate - 365
 group by w.status_id order by w.status_id;
